    int nx , ny;
    for( int i = 0 ; i < t ; ++i ){
        for( int x = 0 ; x < n ; ++x )
            for( int y = 0 ; y < n ; ++y )
                S[ x ][ y ][ i + 1 ] = S[ x ][ y ][ i ];
        for( int x = 0 ; x < n ; ++x ){
            for( int y = 0 ; y < n ; ++y ){
                if( S[ x ][ y ][ i ] == 'Z' ){
                    for( int k = 0 ; k < 4 ; ++k ){
                        nx = dx[ k ] + x;
                        ny = dy[ k ] + y;
                        if( nx >= 0 && ny >= 0 && nx < n && ny < n && S[ nx ][ ny ][ i ] != 'Y'){
                            S[ nx ][ ny ][ i + 1 ] = 'Z';
                        }
                    }
                }
            }
        }
    }
}

void Ver(){
